"""NIST ACVP ML-KEM-1024 keyGen / encaps / decaps vectors, parsed from the
generated C header.

``hw/sys/sep/dv/fw/tests/common/abr_nist_kem_vectors.h`` is generated by
``fw/tests/common/gen_abr_nist_vectors.py --mlkem`` from the NIST ACVP-Server
internalProjection at the commit the header names. This module is the Python
golden for the no_cpu ML-KEM KAT; it does not re-encode the words.

The decaps pair is the load-bearing part. FIPS-203 uses implicit rejection: a
modified ciphertext does not raise an error, it yields a DIFFERENT shared key.
So the rejecting case carries its own expected K and is graded by value. Each
ACVP decaps case has its own decapsulation key, so the two are not one key
walked twice and neither can be derived from the other.

``NIST_KEM_DEC_MODIFIED`` holds every ML-KEM-1024 decaps case with reason
"modified ciphertext", each with its ACVP ``tcId`` and its own K.
``NIST_KEM_DEC_BAD_*`` is the tcId 96 row of the table. The K values of the
table and the valid case K are pairwise different, so a returned K names the
case that produced it.

Same limit as ``sep_abr_nist``: these are transcribed authority values, not a
recomputable construction. The generated header is the vector source.
Import-time assertions check shape, non-degeneracy and table consistency only;
they do not detect a same-length transcription error.
"""

from __future__ import annotations

import re
from dataclasses import dataclass
from pathlib import Path

_HEADER = Path(__file__).resolve().parents[2] / "fw" / "tests" / "common" / "abr_nist_kem_vectors.h"
_TEXT = _HEADER.read_text(encoding="utf-8")


def _load_u32_array(name: str) -> list[int]:
    m = re.search(
        rf"static const uint32_t {name}\[(\d+)\] = \{{(.*?)\}};",
        _TEXT,
        re.S,
    )
    if not m:
        raise RuntimeError(f"{name} not found in {_HEADER}")
    words = [int(tok, 16) for tok in re.findall(r"0x([0-9a-fA-F]+)u", m.group(2))]
    n = int(m.group(1))
    if len(words) != n:
        raise RuntimeError(f"{name}: parsed {len(words)} words, header says {n}")
    return words


def _load_define(name: str) -> int:
    """One ``#define <name> <int>`` from the header."""
    m = re.search(rf"^#define {name}\s+(\d+)\s*$", _TEXT, re.M)
    if not m:
        raise RuntimeError(f"{name} not found in {_HEADER}")
    return int(m.group(1))


def _load_string(name: str) -> str:
    """One ``#define <name> "<text>"`` from the header."""
    m = re.search(rf'^#define {name}\s+"([^"\\]*)"\s*$', _TEXT, re.M)
    if not m:
        raise RuntimeError(f"{name} not found in {_HEADER}")
    return m.group(1)


@dataclass(frozen=True)
class DecapsCase:
    """One ACVP ML-KEM decaps case: dk and c in, the expected shared key K out."""

    tcid: int
    reason: str
    dk: list[int]
    c: list[int]
    k: list[int]


# keyGen: the two seeds in, the two keys out.
NIST_KEM_KG_D = _load_u32_array("nist_kem_kg_d")
NIST_KEM_KG_Z = _load_u32_array("nist_kem_kg_z")
NIST_KEM_KG_EK = _load_u32_array("nist_kem_kg_ek")
NIST_KEM_KG_DK = _load_u32_array("nist_kem_kg_dk")

# encaps: ek + the message randomness m fix the ciphertext and the shared key.
NIST_KEM_ENC_EK = _load_u32_array("nist_kem_enc_ek")
NIST_KEM_ENC_M = _load_u32_array("nist_kem_enc_m")
NIST_KEM_ENC_C = _load_u32_array("nist_kem_enc_c")
NIST_KEM_ENC_K = _load_u32_array("nist_kem_enc_k")

# decaps: one ACVP "valid decapsulation" case and one "modified ciphertext".
NIST_KEM_DEC_OK_DK = _load_u32_array("nist_kem_dec_ok_dk")
NIST_KEM_DEC_OK_C = _load_u32_array("nist_kem_dec_ok_c")
NIST_KEM_DEC_OK_K = _load_u32_array("nist_kem_dec_ok_k")
NIST_KEM_DEC_OK_TCID = _load_define("NIST_KEM_DEC_OK_TCID")

NIST_KEM_DEC_BAD_DK = _load_u32_array("nist_kem_dec_bad_dk")
NIST_KEM_DEC_BAD_C = _load_u32_array("nist_kem_dec_bad_c")
NIST_KEM_DEC_BAD_K = _load_u32_array("nist_kem_dec_bad_k")
NIST_KEM_DEC_BAD_TCID = _load_define("NIST_KEM_DEC_BAD_TCID")

NIST_KEM_DEC_VALID = DecapsCase(
    tcid=NIST_KEM_DEC_OK_TCID,
    reason="valid decapsulation",
    dk=NIST_KEM_DEC_OK_DK,
    c=NIST_KEM_DEC_OK_C,
    k=NIST_KEM_DEC_OK_K,
)

# Every modified-ciphertext decaps case, in tcId order.
NIST_KEM_DEC_MODIFIED = [
    DecapsCase(
        tcid=_load_define(f"NIST_KEM_DEC_MOD_{_k}_TCID"),
        reason=_load_string(f"NIST_KEM_DEC_MOD_{_k}_REASON"),
        dk=_load_u32_array(f"nist_kem_dec_mod_{_k}_dk"),
        c=_load_u32_array(f"nist_kem_dec_mod_{_k}_c"),
        k=_load_u32_array(f"nist_kem_dec_mod_{_k}_k"),
    )
    for _k in range(_load_define("NIST_KEM_DEC_MOD_COUNT"))
]

# Shapes. ML-KEM-1024: ek 1568 B, dk 3168 B, ct 1568 B, K and each seed 32 B.
_EK_WORDS = 392
_DK_WORDS = 792
_CT_WORDS = 392
_K_WORDS = 8
_SEED_WORDS = 8

for _name, _v, _n in (
    ("NIST_KEM_KG_D", NIST_KEM_KG_D, _SEED_WORDS),
    ("NIST_KEM_KG_Z", NIST_KEM_KG_Z, _SEED_WORDS),
    ("NIST_KEM_ENC_M", NIST_KEM_ENC_M, _SEED_WORDS),
    ("NIST_KEM_KG_EK", NIST_KEM_KG_EK, _EK_WORDS),
    ("NIST_KEM_ENC_EK", NIST_KEM_ENC_EK, _EK_WORDS),
    ("NIST_KEM_KG_DK", NIST_KEM_KG_DK, _DK_WORDS),
    ("NIST_KEM_DEC_OK_DK", NIST_KEM_DEC_OK_DK, _DK_WORDS),
    ("NIST_KEM_DEC_BAD_DK", NIST_KEM_DEC_BAD_DK, _DK_WORDS),
    ("NIST_KEM_ENC_C", NIST_KEM_ENC_C, _CT_WORDS),
    ("NIST_KEM_DEC_OK_C", NIST_KEM_DEC_OK_C, _CT_WORDS),
    ("NIST_KEM_DEC_BAD_C", NIST_KEM_DEC_BAD_C, _CT_WORDS),
    ("NIST_KEM_ENC_K", NIST_KEM_ENC_K, _K_WORDS),
    ("NIST_KEM_DEC_OK_K", NIST_KEM_DEC_OK_K, _K_WORDS),
    ("NIST_KEM_DEC_BAD_K", NIST_KEM_DEC_BAD_K, _K_WORDS),
    *((f"modified tcId {_c.tcid} dk", _c.dk, _DK_WORDS) for _c in NIST_KEM_DEC_MODIFIED),
    *((f"modified tcId {_c.tcid} c", _c.c, _CT_WORDS) for _c in NIST_KEM_DEC_MODIFIED),
    *((f"modified tcId {_c.tcid} k", _c.k, _K_WORDS) for _c in NIST_KEM_DEC_MODIFIED),
):
    assert len(_v) == _n, f"{_name}: {len(_v)} words, expected {_n}"

# Non-degeneracy: an all-zero expected value would pass against a window that
# reads back zero, which is exactly what an unstarted engine returns.
for _name, _v in (
    ("NIST_KEM_KG_EK", NIST_KEM_KG_EK),
    ("NIST_KEM_KG_DK", NIST_KEM_KG_DK),
    ("NIST_KEM_ENC_C", NIST_KEM_ENC_C),
    ("NIST_KEM_ENC_K", NIST_KEM_ENC_K),
    ("NIST_KEM_DEC_OK_K", NIST_KEM_DEC_OK_K),
    ("NIST_KEM_DEC_BAD_K", NIST_KEM_DEC_BAD_K),
    *((f"modified tcId {_c.tcid} k", _c.k) for _c in NIST_KEM_DEC_MODIFIED),
):
    assert any(w != 0 for w in _v), f"{_name} is all zero"

# The implicit-rejection case must differ from the accepting one on both the
# input and the expected output, or the reject leg could not fail.
assert NIST_KEM_DEC_OK_C != NIST_KEM_DEC_BAD_C, "the two decaps ciphertexts are identical"
assert NIST_KEM_DEC_OK_K != NIST_KEM_DEC_BAD_K, (
    "the valid and modified-ciphertext decaps cases expect the same shared key, "
    "so implicit rejection would not be observable"
)

# Modified-ciphertext table: every row has the ACVP reason, tcIds are unique,
# the K values of the table and the valid case K are pairwise different, at
# least two rows remain without tcId 96, and NIST_KEM_DEC_BAD_* is the tcId 96 row.
assert len({_c.tcid for _c in NIST_KEM_DEC_MODIFIED}) == len(NIST_KEM_DEC_MODIFIED), (
    "duplicate tcId in the modified-ciphertext table"
)
for _c in NIST_KEM_DEC_MODIFIED:
    assert _c.reason == "modified ciphertext", f"tcId {_c.tcid} reason {_c.reason!r}"
    assert _c.c != NIST_KEM_DEC_OK_C, f"tcId {_c.tcid} has the valid case ciphertext"
_all_k = [tuple(NIST_KEM_DEC_VALID.k)] + [tuple(_c.k) for _c in NIST_KEM_DEC_MODIFIED]
assert len(set(_all_k)) == len(_all_k), (
    "two decaps cases expect the same shared key, so a returned K does not name its case"
)
assert len([_c for _c in NIST_KEM_DEC_MODIFIED if _c.tcid != 96]) >= 2, (
    "fewer than two modified-ciphertext rows other than tcId 96"
)
_bad_rows = [_c for _c in NIST_KEM_DEC_MODIFIED if _c.tcid == NIST_KEM_DEC_BAD_TCID]
assert NIST_KEM_DEC_BAD_TCID == 96 and len(_bad_rows) == 1, "tcId 96 is not one row of the table"
assert (_bad_rows[0].dk, _bad_rows[0].c, _bad_rows[0].k) == (
    NIST_KEM_DEC_BAD_DK,
    NIST_KEM_DEC_BAD_C,
    NIST_KEM_DEC_BAD_K,
), "NIST_KEM_DEC_BAD_* differs from the tcId 96 row of the modified-ciphertext table"
